{
  "findings": [
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that even with the strictest chat setting ('no one'), in-game chats can still occur if the game itself includes chat.",
      "stance": "risk",
      "quote": "even when chat is set to \"no one,\" if a mini-game has chat built into the game itself, it can't be disabled."
    },
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that users can write text on 'signs' to communicate with everyone in the same game, bypassing parental controls that disable chats.",
      "stance": "risk",
      "quote": "Any user can write text on \"signs\" that their avatar can hold up to communicate a message to everyone who is playing the same game as them, regardless of age."
    },
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that voice chat may not be available for unverified accounts and recommends disabling it for young kids to limit communication with unfamiliar people.",
      "stance": "mitigation",
      "quote": "For young kids, we recommend disabling voice chat to limit communication with unfamiliar people—particularly because kids can be exposed to a stream of vulgar audio from other kids and adults, which can play in the background as kids navigate mini-games."
    },
    {
      "ref": "[D520]",
      "area": "money",
      "claim": "A parent reports that Roblox allows setting a monthly spending limit on how much money a child can spend.",
      "stance": "mitigation",
      "quote": "You can set a monthly spending limit on how much money your child can spend on Roblox."
    },
    {
      "ref": "[D520]",
      "area": "data",
      "claim": "A parent reports that Roblox can collect data and share it, but users under 13 are not subject to ad personalization.",
      "stance": "neutral",
      "quote": "Ad personalization does not apply to users under the age of 13."
    },
    {
      "ref": "[D520]",
      "area": "age_gating",
      "claim": "A parent reports that experiences labeled as containing sensitive issues are blocked by default for users under 16, though parents can change this setting.",
      "stance": "mitigation",
      "quote": "By default, users under 16 cannot access experiences that are labeled as including sensitive issues, though parents can change this in the Sensitive issues settings."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ contain intense violence and inappropriate themes, such as fiery car accidents and prompts to shoot or save an officer.",
      "stance": "risk",
      "quote": "Within seconds, this \"Street Code\" game showed an intense, fiery car accident and prompted the player to decide whether to shoot or save an officer."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that the 'Baddies' game is labeled for age 5+ and encourages punching, stomping, shooting, and other violence as part of the opening tutorial.",
      "stance": "risk",
      "quote": "This \"Baddies\" game is labeled for age 5+ and encourages punching, stomping, shooting, and other violence as part of the opening tutorial."
    },
    {
      "ref": "[D520]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox does not alert parents to inappropriate content, even with the most strict settings.",
      "stance": "risk",
      "quote": "Roblox does not alert parents to inappropriate content. Even with the most strict settings, it is still possible to access harmful content if left unmonitored."
    }
  ]
}
